 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  FAR const char *recognized;
  int ret;

  printf("Hello, AI Glasses World!!\n");

  /* Run the (simulated) image recognition and read the result aloud using
   * the pre-rendered speech clip for the recognized text.
   */

  recognized = image_recognition_demo();
  printf("ai_glasses: recognition result: %s\n", recognized);

  ret = speak_text(recognized);
  if (ret < 0)
    {
      printf("ai_glasses: FAILED to produce speech WAV (%d)\n", ret);
      return ret;
