/* Simulate an on-device image-recognition inference.  In a real product the
 * camera frame would be fed to a neural-network accelerator and the top
 * classification returned.  Here we just cycle (round-robin) through every
 * phrase that has a pre-rendered voice clip in g_tts_phrases[] so the demo
 * stays self-consistent: whatever text the "recognizer" returns always has a
 * matching clip to read it aloud.
 */

static FAR const char *image_recognition_demo(void)
{
  static unsigned int next;
  FAR const char *result;

  result = g_tts_phrases[next].text;
  next = (next + 1) % TTS_PHRASE_COUNT;

  return result;
}

