/* Simulate an on-device image-recognition inference.  First capture a real
 * frame from the camera device; then, since there is no neural network in
 * this example, return a simulated top-1 classification.  The result cycles
 * (round-robin) through every phrase that has a pre-rendered voice clip in
 * g_tts_phrases[] so the demo stays self-consistent: whatever text the
 * "recognizer" returns always has a matching clip to read it aloud.
 */

static FAR const char *image_recognition_demo(void)
{
  static unsigned int next;
  FAR uint8_t *frame = NULL;
  FAR const char *result;
  uint32_t frame_size = 0;
  uint32_t sum = 0;
  uint32_t samples = 0;
  uint32_t k;
  uint8_t avg_luma = 0;

  if (camera_grab(&frame, &frame_size) == 0 && frame != NULL)
    {
      for (k = 0; k < frame_size; k += 97)
        {
          sum += frame[k];
          samples++;
        }

      avg_luma = samples != 0 ? (uint8_t)(sum / samples) : 0;
      printf("ai_glasses: captured %lu bytes from %s (avg luma %u)\n",
             (unsigned long)frame_size, CAMERA_DEV_PATH, avg_luma);
      free(frame);
    }
  else
    {
      printf("ai_glasses: camera grab failed; using simulated frame\n");
    }

  result = g_tts_phrases[next].text;
  next = (next + 1) % TTS_PHRASE_COUNT;

  return result;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * ai_glasses_main
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  FAR const char *recognized;
  int frame;
  int ret;

  printf("Hello, AI Glasses World!!\n");

  /* Simulate a short continuous-recognition session: classify one frame per
   * known result.  image_recognition_demo() cycles round-robin, so every
   * recognized text (and its pre-rendered voice clip) is exercised in turn.
   */

  for (frame = 0; frame < TTS_PHRASE_COUNT; frame++)
    {
      printf("\nai_glasses: ---- camera frame %d ----\n", frame + 1);

      recognized = image_recognition_demo();
      printf("ai_glasses: recognition result: %s\n", recognized);

      ret = speak_text(recognized);
      if (ret < 0)
        {
          printf("ai_glasses: FAILED to produce speech WAV (%d)\n", ret);
          return ret;
        }

      /* Push the speech WAV to the audio device.  On targets without a codec
       * (e.g. the qemu board registers only AUDIO_NULL) nxplayer reports that
       * no audio device is available and exits; the WAV itself stays in /data
       * for inspection.
       */

      ret = play_wav();
      printf("ai_glasses: frame %d spoken (\"%s\", WAV %s, playback %s)\n",
             frame + 1, recognized, WAV_PATH,
             ret == 0 ? "OK" : "not audible on this board");
    }

  printf("\nai_glasses: recognition demo done (%u frames)\n",
         (unsigned int)TTS_PHRASE_COUNT);

  return 0;
}

