/* Number of camera frames to classify and announce per demo run.  Real
 * inference is slow on the emulated CPU; lower this if a run cannot finish.
 */

#define AI_GLASSES_FRAMES  5

/* Down-sample a captured QVGA RGB565 frame to the model's 96x96 greyscale
 * input using nearest-neighbour sampling and luma (Rec. 601) conversion. */

static void frame_to_gray96(FAR const uint8_t *rgb565,
                            FAR uint8_t *gray96)
{
  int y;
  int x;

  for (y = 0; y < AI_GLASSES_ML_ROWS; y++)
    {
      int sy = (y * CAM_HEIGHT) / AI_GLASSES_ML_ROWS;
      for (x = 0; x < AI_GLASSES_ML_COLS; x++)
        {
          int sx = (x * CAM_WIDTH) / AI_GLASSES_ML_COLS;
          uint32_t off = (uint32_t)(sy * CAM_WIDTH + sx) * 2;
          uint16_t px = (uint16_t)(rgb565[off] | (rgb565[off + 1] << 8));
          uint8_t r = (uint8_t)((px >> 11) & 0x1f);
          uint8_t g = (uint8_t)((px >> 5) & 0x3f);
          uint8_t b = (uint8_t)(px & 0x1f);
          uint8_t r8 = (uint8_t)((r << 3) | (r >> 2));
          uint8_t g8 = (uint8_t)((g << 2) | (g >> 4));
          uint8_t b8 = (uint8_t)((b << 3) | (b >> 2));

          gray96[y * AI_GLASSES_ML_COLS + x] =
            (uint8_t)((77u * r8 + 150u * g8 + 29u * b8) >> 8);
        }
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * ai_glasses_main
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  struct ai_glasses_ml_result_s mres;
  FAR const char *recognized;
  int frame;
  int ret;

  printf("Hello, AI Glasses World!!\n");

  /* Build the person_detect (TFLite Micro) interpreter once. */

  ret = ai_glasses_ml_init();
  if (ret < 0)
    {
      printf("ai_glasses: FAILED to init person_detect model (%d)\n", ret);
      return ret;
    }

  printf("ai_glasses: person_detect (TFLite Micro) ready\n");

  /* Continuous recognition: capture a frame from the camera, run the real
   * model on it, print the confidence, and read the result aloud.
   */

  for (frame = 0; frame < AI_GLASSES_FRAMES; frame++)
    {
      FAR uint8_t *cap = NULL;
      uint32_t cap_size = 0;
      uint8_t gray[AI_GLASSES_ML_ROWS * AI_GLASSES_ML_COLS];

      printf("\nai_glasses: ---- camera frame %d ----\n", frame + 1);

      ret = camera_grab(&cap, &cap_size);
      if (ret != 0 || cap == NULL)
        {
          printf("ai_glasses: camera grab failed (%d); skipping frame\n",
                 ret);
          continue;
        }

      printf("ai_glasses: captured %lu bytes from %s\n",
             (unsigned long)cap_size, CAMERA_DEV_PATH);
      frame_to_gray96(cap, gray);
      free(cap);

      ret = ai_glasses_ml_run(gray, &mres);
      if (ret != 0)
        {
          printf("ai_glasses: person_detect inference failed (%d)\n", ret);
          continue;
        }

      printf("ai_glasses: top-1 = %-9s conf %.2f  "
             "(person %.2f / notperson %.2f)\n",
             mres.label, mres.confidence, mres.conf[AI_GLASSES_ML_PERSON],
             mres.conf[AI_GLASSES_ML_NOTPERSON]);

      recognized = (mres.class_id == AI_GLASSES_ML_PERSON) ?
                   "Person detected" : "No person detected";

      ret = speak_text(recognized);
      if (ret < 0)
        {
          printf("ai_glasses: FAILED to produce speech WAV (%d)\n", ret);
          return ret;
        }

      /* Push the speech WAV to the audio device.  On targets without a codec
       * (e.g. the qemu board registers only AUDIO_NULL) nxplayer reports that
       * no audio device is available and exits; the WAV itself stays in /data
       * for inspection.
       */

      ret = play_wav();
      printf("ai_glasses: frame %d spoken (\"%s\", playback %s)\n",
             frame + 1, recognized,
             ret == 0 ? "OK" : "not audible on this board");
    }

  printf("\nai_glasses: real-inference demo done (%d frames)\n",
         AI_GLASSES_FRAMES);

  return 0;
}

